SINA_SMART["biophys1-hearing"] = {"lecture":"biophys1-hearing","title":"Biophysics of hearing","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"biophys1-hearing:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"insufficient-source"},{"id":"biophys1-hearing:e0","text":"Sound: mechanical wave; frequency = pitch, amplitude = loudness; c ≈ 343 m/s in air.","topic":"Physics of sound","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e1","text":"Hearing range of pressure: 20 µPa to 20 Pa.","topic":"Physics of sound","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e2","text":"dB = 20 log₁₀(P/20 µPa); +10 dB = 10× intensity ≈ 2× loudness.","topic":"Physics of sound","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e3","text":"Weber-Fechner: perception is logarithmic.","topic":"Physics of sound","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e4","text":"Best sensitivity 2-4 kHz; canal resonance 2.5-3 kHz.","topic":"Physics of sound","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e5","text":"Middle ear: impedance matching, ×22 pressure; otherwise 99% reflected.","topic":"The ear","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e6","text":"Cochlea: base = high frequencies (stiff, narrow); apex = low (wide, floppy).","topic":"The ear","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e7","text":"Inner hair cells detect; outer hair cells amplify.","topic":"The ear","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e8","text":"Pathway: cochlear nucleus → olive → inferior colliculus → MGB → cortex; bilateral.","topic":"The ear","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biophys1-hearing:e9","text":"Conductive: air ↓ bone normal. Sensorineural: both ↓. Aids vs cochlear implants.","topic":"Audiometry and hearing loss","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1bes083":"a","2fu8os":"a","w2ipme":"a","10meu3j":"a","u3h3an":"a","1wnzixh":"a","11006ik":"a","1hmil6w":"a","1r9djd1":"a","1e5353x":"a","3aaefe":"a","rvp52":"a","b1xu7":"a","1uzc0t":"a","604aay":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"biophys1-hearing:s0":{"s":0,"u":["The ear turns pressure waves in air into nerve signals: the outer and middle ear transmit sound, the inner ear perceives it (and also serves balance).","Understanding the physics explains decibels, why speech frequencies are heard best, and how hearing loss is diagnosed and treated."],"dp":[]},"biophys1-hearing:e0":{"s":1,"u":["Sound: mechanical wave; frequency = pitch, amplitude = loudness; c ≈ 343 m/s in air.","Sound is a mechanical wave in a medium, defined by frequency (pitch), amplitude (loudness) and phase; speed in air ≈ 343 m/s at 20 °C; λ = c/f ."],"dp":[]},"biophys1-hearing:e1":{"s":1,"u":["Hearing range of pressure: 20 µPa to 20 Pa.","The ear detects pressures from about 20 µPa to 20 Pa .","Intensity ∝ pressure², so doubling pressure quadruples intensity."],"dp":[]},"biophys1-hearing:e2":{"s":1,"u":["dB = 20 log₁₀(P/20 µPa); +10 dB = 10× intensity ≈ 2× loudness.","Intensity ∝ pressure², so doubling pressure quadruples intensity.","Sound pressure level: dB = 20·log₁₀(P/P_ref) , with P_ref = 20 µPa (hearing threshold). +10 dB = 10× intensity , perceived as about twice as loud ."],"dp":[]},"biophys1-hearing:e3":{"s":1,"u":["Weber-Fechner: perception is logarithmic.","Loudness is subjective; by the Weber-Fechner law perception grows logarithmically with intensity."],"dp":[]},"biophys1-hearing:e4":{"s":1,"u":["Best sensitivity 2-4 kHz; canal resonance 2.5-3 kHz.","The ear is most sensitive at 2-4 kHz (speech consonants): equal SPL does not mean equal loudness (a 3 kHz tone at 60 dB sounds louder than a 50 Hz tone at 60 dB)."],"dp":[]},"biophys1-hearing:e5":{"s":2,"u":["Middle ear: impedance matching, ×22 pressure; otherwise 99% reflected.","Middle ear : impedance matching between air and cochlear fluid (without it ~99% of energy would be reflected): the ossicles (malleus → incus → stapes) act as a lever and the pressure rises about 22× ."],"dp":[{"h":"Why the middle ear is needed","t":"Sound in air carries little pressure but lots of movement; cochlear fluid needs high pressure to move. Sending airborne sound straight into fluid would reflect almost all the energy, as happens when you shout at a swimming pool. The large eardrum funnels force onto the tiny stapes footplate and the ossicle lever adds leverage, multiplying pressure about 22 times. Source: the lecture's middle ear function slide."}]},"biophys1-hearing:e6":{"s":2,"u":["Cochlea: base = high frequencies (stiff, narrow); apex = low (wide, floppy).","The basilar membrane is stiff and narrow at the base (high frequencies) and wide and floppy at the apex (low frequencies) : a travelling wave peaks at each frequency's place ( tonotopy )."],"dp":[]},"biophys1-hearing:e7":{"s":2,"u":["Inner hair cells detect; outer hair cells amplify.","Organ of Corti : inner hair cells detect (transduction); outer hair cells amplify ."],"dp":[]},"biophys1-hearing:e8":{"s":2,"u":["Pathway: cochlear nucleus → olive → inferior colliculus → MGB → cortex; bilateral.","Pathway : auditory nerve → cochlear nucleus → superior olivary complex → inferior colliculus → medial geniculate body (thalamus) → auditory cortex; bilateral projections give redundancy and localisation."],"dp":[]},"biophys1-hearing:e9":{"s":3,"u":["Conductive: air ↓ bone normal. Sensorineural: both ↓. Aids vs cochlear implants.","Air ↓, bone normal → conductive loss (outer/middle ear: wax , otitis media , otosclerosis fixing the stapes).","Treatment: hearing aids amplify the frequencies poorly heard and reduce noise digitally (mild-moderate sensorineural loss); cochlear implants bypass destroyed hair cells and stimulate the auditory nerve directly."],"dp":[{"h":"Why air vs bone conduction pinpoints the problem","t":"Bone conduction vibrates the skull and reaches the cochlea directly, skipping the outer and middle ear. If a patient hears poorly through headphones but normally through bone, the cochlea works and the block is in transmission (conductive). If both are equally poor, the cochlea or nerve is damaged (sensorineural). Source: the lecture's audiometry slides."}]}},"meta":{"1bes083":{"a":"recall","vg":"biophys1-hearing:e0/recall/1"},"2fu8os":{"a":"recall","vg":"biophys1-hearing:e1/recall/1"},"w2ipme":{"a":"recall","vg":"biophys1-hearing:e2/recall/1"},"10meu3j":{"a":"application","vg":"biophys1-hearing:e1/application/1"},"u3h3an":{"a":"recall","vg":"biophys1-hearing:e3/recall/1"},"1wnzixh":{"a":"recall","vg":"biophys1-hearing:e4/recall/1"},"11006ik":{"a":"recall","vg":"biophys1-hearing:e4/recall/1"},"1hmil6w":{"a":"recall","vg":"biophys1-hearing:e5/recall/1"},"1r9djd1":{"a":"application","vg":"biophys1-hearing:e5/application/1"},"1e5353x":{"a":"recall","vg":"biophys1-hearing:e6/recall/1"},"3aaefe":{"a":"recall","vg":"biophys1-hearing:e7/recall/1"},"rvp52":{"a":"recall","vg":"biophys1-hearing:e8/recall/1"},"b1xu7":{"a":"recall","vg":"biophys1-hearing:e9/recall/1"},"1uzc0t":{"a":"recall","vg":"biophys1-hearing:e9/recall/2"},"604aay":{"a":"recall","vg":"biophys1-hearing:e9/recall/3"}},"explRev":"d8441d1ec653"};
